script.setup:
// Perfect Freehand turns pointer samples into the outline of a pressure-sensitive stroke;
// WebGL fills each outline (signed triangle fans) and bakes finished strokes into a paper layer.
const mod = await ctx.utils.import("https://esm.sh/perfect-freehand@1.2.3");
const getStroke = mod.getStroke ?? mod.default;
const gl = ctx.gl;
gl.getExtension("EXT_color_buffer_float");
const flat = ctx.utils.createProgram(`#version 300 es
layout(location=0) in vec2 a_position; layout(location=1) in vec4 a_color;
uniform vec2 u_px; out vec4 v_color;
void main(){ v_color = a_color; gl_Position = vec4(a_position / u_px * 2.0 - 1.0, 0.0, 1.0); }`, `#version 300 es
precision highp float; in vec4 v_color; out vec4 outColor;
void main(){ outColor = v_color; }`);
const vao = gl.createVertexArray(), vbo = gl.createBuffer();
gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 24, 0);
gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 4, gl.FLOAT, false, 24, 8);
gl.bindVertexArray(null);
const kit = {
  // Draws a flat (x, y, r, g, b, a) triangle list.
  draw(arr) {
    if (!arr.length) return;
    gl.useProgram(flat);
    ctx.utils.setUniforms(flat, { u_px: ctx.resolution });
    gl.bindVertexArray(vao); gl.bindBuffer(gl.ARRAY_BUFFER, vbo);
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array(arr), gl.DYNAMIC_DRAW);
    gl.drawArrays(gl.TRIANGLES, 0, arr.length / 6);
    gl.bindVertexArray(null);
  },
  // Signed triangle fan: inside a closed ring the triangles add up to ±c, outside they cancel.
  // Summed with additive blending, this fills any polygon (holes, self-overlaps) exactly.
  fan(ring, c, out) {
    const x0 = ring[0], y0 = ring[1];
    for (let i = 2; i + 3 < ring.length; i += 2) {
      const s = Math.sign((ring[i] - x0) * (ring[i + 3] - y0) - (ring[i + 1] - y0) * (ring[i + 2] - x0));
      if (!s) continue;
      out.push(x0, y0, c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i], ring[i + 1], c[0] * s, c[1] * s, c[2] * s, c[3] * s,
        ring[i + 2], ring[i + 3], c[0] * s, c[1] * s, c[2] * s, c[3] * s);
    }
  },
  // Thick polyline as quads (WebGL lines are 1 px); square ends overlap at the joints.
  line(pts, closed, width, c, out) {
    const n = pts.length / 2, hw = width / 2;
    for (let i = 0; i < (closed ? n : n - 1); i++) {
      const j = (i + 1) % n;
      const ax = pts[i * 2], ay = pts[i * 2 + 1], bx = pts[j * 2], by = pts[j * 2 + 1];
      const len = Math.hypot(bx - ax, by - ay);
      if (len < 1e-6) continue;
      const dx = (bx - ax) / len * hw, dy = (by - ay) / len * hw;
      const p = [ax - dx - dy, ay - dy + dx, ax - dx + dy, ay - dy - dx, bx + dx + dy, by + dy - dx, bx + dx - dy, by + dy + dx];
      for (const k of [0, 1, 2, 0, 2, 3]) out.push(p[k * 2], p[k * 2 + 1], c[0], c[1], c[2], c[3]);
    }
  },
  // Disc made of triangles.
  dot(x, y, r, c, out, seg = 16) {
    for (let i = 0; i < seg; i++) {
      const a0 = i / seg * 6.2832, a1 = (i + 1) / seg * 6.2832;
      out.push(x, y, ...c, x + Math.cos(a0) * r, y + Math.sin(a0) * r, ...c, x + Math.cos(a1) * r, y + Math.sin(a1) * r, ...c);
    }
  },
  acc: null,
  // Renders signed fans additively into a half-float target at up to 2x the canvas size
  // (sampling it back with linear filtering smooths the edges). Returns the texture.
  accumulate(arr) {
    const [w, h] = ctx.resolution, k = Math.min(2, 4096 / Math.max(w, h));
    const tw = Math.round(w * k), th = Math.round(h * k);
    if (!kit.acc) kit.acc = ctx.utils.createPingPong(tw, th, { internalFormat: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT });
    else if (kit.acc.width !== tw || kit.acc.height !== th) kit.acc.resize(tw, th);
    const t = kit.acc.read();
    gl.bindFramebuffer(gl.FRAMEBUFFER, t.framebuffer); gl.viewport(0, 0, tw, th);
    gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT);
    gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE);
    kit.draw(arr);
    gl.disable(gl.BLEND);
    gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.viewport(0, 0, w, h);
    return t.texture;
  },
};
const s = ctx.state;
Object.assign(s, { kit, getStroke, strokes: [], current: null, paper: null, dirty: true, key: "" });
// Strokes are stored in units of the canvas height (y up) so they survive a resize.
const demo = (fn, n, hue) => {
  const pts = [];
  // Uneven spacing reads as uneven speed, which the simulated pressure turns into width.
  for (let i = 0; i <= n; i++) { const t = i / n; pts.push(fn(t + Math.sin(t * 6.283 * 3) * 0.035)); }
  s.strokes.push({ pts, hue });
};
const [w, h] = ctx.resolution, A = w / h;
// A loopy "signature", a spiral and a wave, drawn as if by hand.
demo((t) => [A * 0.5 - 0.62 + t * 1.24 + 0.07 * Math.cos(t * 50), 0.68 + 0.09 * Math.sin(t * 50) + 0.03 * Math.sin(t * 7)], 260, 0);
demo((t) => { const a = t * 15, r = 0.02 + t * 0.15; return [A * 0.5 - 0.42 + Math.cos(a) * r, 0.32 + Math.sin(a) * r]; }, 220, 1);
demo((t) => [A * 0.5 - 0.05 + t * 0.52, 0.32 + 0.1 * Math.sin(t * 12) * (1 - t * 0.5)], 160, 2);
s.stroke = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor; uniform sampler2D u_src;
void main(){
  vec4 t = texture(u_src, v_uv);
  // Winding sum: colour / coverage, both signed the same way.
  float a = abs(t.a);
  outColor = a > 1e-3 ? vec4(t.rgb / t.a, min(a, 1.0)) : vec4(0.0);
}`);
s.show = ctx.utils.createProgram(ctx.utils.FULLSCREEN_VERTEX_SHADER, `#version 300 es
precision highp float; in vec2 v_uv; out vec4 outColor;
uniform sampler2D u_paper; uniform vec3 u_bg; uniform vec2 u_resolution;
float hash(vec2 p){ return fract(sin(dot(p, vec2(12.9898, 78.233))) * 43758.5453); }
void main(){
  vec4 ink = texture(u_paper, v_uv);
  vec2 q = v_uv * u_resolution;
  float grain = (hash(floor(q / 2.0)) - 0.5) * 0.035;
  float vig = 1.0 - 0.25 * pow(length(v_uv - 0.5) * 1.3, 2.0);
  vec3 bg = (u_bg + grain) * vig;
  outColor = vec4(bg * (1.0 - ink.a) + ink.rgb, 1.0); // paper holds premultiplied ink
}`);
s.wasDown = false;

script.render:
const s = ctx.state, gl = ctx.gl, u = ctx.uniforms, kit = s.kit;
const [w, h] = ctx.resolution;
const opts = { size: u.u_size * h * 0.01, thinning: u.u_thinning, smoothing: u.u_smoothing, streamline: u.u_streamline,
  simulatePressure: true, start: { taper: u.u_taper * h * 0.1 }, end: { taper: u.u_taper * h * 0.1 } };
const palette = [u.u_ink1, u.u_ink2, u.u_ink3];
const fillsOf = (st, last) => {
  const pts = st.pts.map(([x, y]) => [x * h, y * h]);
  const outline = s.getStroke(pts, { ...opts, last });
  const flatPts = [];
  for (const p of outline) flatPts.push(p[0], p[1]);
  const c = palette[st.hue % 3], out = [];
  kit.fan(flatPts, [c[0], c[1], c[2], 1], out);
  return out;
};
// Pointer: press to start a stroke, drag to draw, release to bake it into the paper.
const [mx, my] = ctx.mouse, p = [mx * w / h, 1 - my];
if (ctx.mouseDown && !s.wasDown) s.current = { pts: [p], hue: s.strokes.length % 3 };
else if (ctx.mouseDown && s.current) {
  const q = s.current.pts[s.current.pts.length - 1];
  if (Math.hypot(p[0] - q[0], p[1] - q[1]) > 0.002) s.current.pts.push(p);
} else if (!ctx.mouseDown && s.current) {
  s.strokes.push(s.current); s.current = null; s.dirty = true;
  if (s.strokes.length > 200) s.strokes.shift();
}
s.wasDown = ctx.mouseDown;
if (u.u_clear) { s.strokes = []; s.dirty = true; }
// Re-bake every stroke when the size or a stroke option changes.
const key = [w, h, u.u_size, u.u_thinning, u.u_smoothing, u.u_streamline, u.u_taper, ...u.u_ink1, ...u.u_ink2, ...u.u_ink3].join();
if (key !== s.key) { s.key = key; s.dirty = true; }
const blendStroke = (fills) => {
  const tex = kit.accumulate(fills);
  gl.enable(gl.BLEND); gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA);
  gl.useProgram(s.stroke); ctx.utils.bindTexture(s.stroke, "u_src", tex, 0);
  ctx.utils.drawFullscreen(s.stroke);
  gl.disable(gl.BLEND);
};
if (!s.paper || s.paper.width !== w || s.paper.height !== h) {
  s.paper = ctx.utils.createPingPong(w, h, {});
  s.dirty = true;
}
if (s.dirty) {
  s.dirty = false;
  const target = s.paper.read();
  for (const st of [null, ...s.strokes]) {
    const fills = st ? fillsOf(st, true) : [];
    gl.bindFramebuffer(gl.FRAMEBUFFER, target.framebuffer); gl.viewport(0, 0, w, h);
    if (!st) { gl.clearColor(0, 0, 0, 0); gl.clear(gl.COLOR_BUFFER_BIT); continue; }
    const tex = kit.accumulate(fills);
    gl.bindFramebuffer(gl.FRAMEBUFFER, target.framebuffer); gl.viewport(0, 0, w, h);
    // Stroke "over" paper; alpha accumulates the usual way.
    gl.enable(gl.BLEND); gl.blendFuncSeparate(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA, gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
    gl.useProgram(s.stroke); ctx.utils.bindTexture(s.stroke, "u_src", tex, 0);
    ctx.utils.drawFullscreen(s.stroke);
    gl.disable(gl.BLEND);
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null); gl.viewport(0, 0, w, h);
}
gl.useProgram(s.show); ctx.utils.bindTexture(s.show, "u_paper", s.paper.read().texture, 0);
ctx.utils.drawFullscreen(s.show);
// The stroke being drawn is filled live on top.
if (s.current && s.current.pts.length > 1) blendStroke(fillsOf(s.current, false));
ctx.publish("strokes", s.strokes.length);
